func newFixture(t *testing.T) *fixture {
	t.Helper()
	dir := t.TempDir()
	f := &fixture{t: t, layout: Layout{Root: filepath.Join(dir, "root"), Owner: os.Getuid()},
		baked: filepath.Join(dir, "baked-binary"), now: time.Now().UTC().Truncate(time.Second)}
	if err := os.WriteFile(f.baked, []byte("baked orchestrator"), 0o755); err != nil {
		t.Fatal(err)
	}
	var rootPublic ed25519.PublicKey
	var err error
	rootPublic, f.rootPrivate, err = ed25519.GenerateKey(rand.Reader)
	if err != nil {
		t.Fatal(err)
	}
	f.leafPublic, f.leafPrivate, err = ed25519.GenerateKey(rand.Reader)
	if err != nil {
		t.Fatal(err)
	}
	f.nodePublic, f.nodePrivate, err = ed25519.GenerateKey(rand.Reader)
	if err != nil {
		t.Fatal(err)
	}
	f.roots, err = trust.ParseKeyring(rootPublic)
	if err != nil {
		t.Fatal(err)
	}
	return f
}

func digestOf(data []byte) string {
	sum := sha256.Sum256(data)
	return hex.EncodeToString(sum[:])
}

func binaryReceipt(data []byte, qualification string) release.BinaryReceipt {
	machine := map[string]string{"amd64": "Advanced Micro Devices X86-64", "arm64": "AArch64"}[runtime.GOARCH]
	return release.BinaryReceipt{
		Schema: release.BinarySchema, SourceRevision: testSource, GoVersion: release.DefaultGoVersion,
		GOOS: "linux", GOARCH: runtime.GOARCH, ELFMachine: machine, Static: true,
		Bytes: int64(len(data)), SHA256: digestOf(data), QualificationSHA256: qualification,
	}
}

func (f *fixture) leafIdentity() (string, string) {
	keyID, err := trust.KeyID(f.leafPublic)
	if err != nil {
		f.t.Fatal(err)
	}
	encoded, err := trust.EncodeDelegatedPublicKey(f.leafPublic)
	if err != nil {
		f.t.Fatal(err)
	}
	return keyID, encoded
}

func (f *fixture) legacySigned(data []byte) ([]byte, []byte) {
	f.t.Helper()
	keyID, encoded := f.leafIdentity()
	delegation, err := trust.SignDelegation(trust.Delegation{
		SchemaVersion: trust.SchemaVersion, SubjectKeyID: keyID, SubjectPublicKey: encoded,
		Capabilities: []trust.Capability{{Domain: release.BinaryDomain, DeploymentID: entityid.Derive("build", testSource), Cell: "BUILD",
			Environment: "canary", Role: "artifact", Slots: []string{"linux-" + runtime.GOARCH}, Actions: []string{"sign"}}},
	}, f.now.Add(-time.Minute), f.now.Add(time.Hour), f.rootPrivate)
	if err != nil {
		f.t.Fatal(err)
	}
	receipt, err := release.SignBinaryReceipt(binaryReceipt(data, digestOf([]byte("q"))), "canary", delegation, f.roots,
		f.leafPrivate, f.now, 30*time.Minute)
	if err != nil {
		f.t.Fatal(err)
	}
	return f.encode(receipt), f.encode(delegation)
}

func (f *fixture) signed(data []byte) ([]byte, []byte) {
	f.t.Helper()
	keyID, encoded := f.leafIdentity()
	delegation, err := release.SignUpdateDelegation(release.BinaryUpdateDelegation{
		Schema: release.UpdateDelegationSchema, SubjectKeyID: keyID, SubjectPublicKey: encoded,
		Environment: "canary", Architectures: []string{runtime.GOARCH},
		Repository: release.QualificationRepository, Workflow: release.QualificationWorkflow,
		Ref: release.LineageRef, LineageBase: strings.Repeat("9", 40),
	}, f.now.Add(-time.Minute), f.now.Add(time.Hour), f.rootPrivate)
	if err != nil {
		f.t.Fatal(err)
	}
	digest := digestOf(data)
	qualification := release.Qualification{
		Schema: release.QualificationSchema, Repository: release.QualificationRepository,
		SourceRevision: testSource, SourceTree: testSource, GoVersion: release.DefaultGoVersion,
		GoModSHA256: digest, GoSumSHA256: digest,
		Verification: release.QualificationCheck{Workflow: release.QualificationWorkflow, Job: release.QualificationJob,
			RunID: 10, RunNumber: 5, Conclusion: "success"},
		Artifacts: []release.QualifiedArtifact{
			{Architecture: "amd64", Name: "terrascale-orchestrator-linux-amd64", Bytes: int64(len(data)), SHA256: digest},
			{Architecture: "arm64", Name: "terrascale-orchestrator-linux-arm64", Bytes: int64(len(data)), SHA256: digest},
		},
	}
	qualificationDigest := digestOf([]byte("qualification"))
	receipt, err := release.SignBinaryUpdateReceipt(binaryReceipt(data, qualificationDigest), qualification, qualificationDigest,
		"GRU", "canary", anyLineage{}, delegation, f.roots, f.leafPrivate, f.now, 30*time.Minute)
	if err != nil {
		f.t.Fatal(err)
	}
	qualified := release.ProductionQualification{Schema: release.ProductionQualificationSchema,
		Candidate: release.ProductionExpectation{SourceRevision: testSource, ArtifactSHA256: digest,
			QualificationSHA256: qualificationDigest, Cell: "GRU", Environment: "canary",
			Runtime: release.ProductionRuntime, Architecture: runtime.GOARCH, Role: "orchestrator"}}
	for _, gate := range []string{"runtime-ha", "workload-safety"} {
		evidence := []byte("test-only " + gate + " evidence")
		qualified.Evidence = append(qualified.Evidence, release.ProductionGateEvidence{Gate: gate,
			SHA256: digestOf(evidence), Bytes: int64(len(evidence)), CompletedAt: f.now.Add(-time.Second)})
	}
	payload, err := trust.EncodePayload(qualified)
	if err != nil {
		f.t.Fatal(err)
	}
	proof, err := trust.Sign(payload, release.ProductionQualificationScope(qualified.Candidate), f.now, f.now.Add(30*time.Minute), f.rootPrivate)
	if err != nil {
		f.t.Fatal(err)
	}
	receipt, err = release.AttachProductionQualification(receipt, release.ProductionProof{Qualification: f.encode(proof)},
		f.encode(delegation), f.roots, f.leafPrivate,
		release.UpdateExpectation{Environment: "canary", Cell: "GRU", Architecture: runtime.GOARCH}, f.now)
	if err != nil {
		f.t.Fatal(err)
	}
	return f.encode(receipt), f.encode(delegation)
}

func (f *fixture) encode(envelope trust.Envelope) []byte {
	wire, err := trust.EncodeEnvelope(envelope)
	if err != nil {
		f.t.Fatal(err)
	}
	return wire
}

func (f *fixture) policy() ReceiptPolicy {
	return ReceiptPolicy{Roots: f.roots, Environment: "canary", Cell: "GRU", Architecture: runtime.GOARCH}
}

func (f *fixture) stage(data []byte) string {
	f.t.Helper()
	receipt, delegation := f.signed(data)
	digest, err := Stage(f.layout, bytes.NewReader(data), receipt, delegation, f.policy(), f.now)
	if err != nil {
		f.t.Fatal(err)
	}
	return digest
}

func (f *fixture) proof(activation Activation, at time.Time) ProofCheck {
	f.t.Helper()
	wire, err := SignVersionProof(VersionProof{Schema: ProofSchema, ActivationID: activation.ActivationID, Unit: activation.Unit,
		BinarySHA256: activation.Target, ProcessID: int64(os.Getpid()), ObservedAt: at}, f.nodePrivate, at)
	if err != nil {
		f.t.Fatal(err)
	}
	path := filepath.Join(f.t.TempDir(), "proof.json")
	if err := os.WriteFile(path, wire, 0o644); err != nil {
		f.t.Fatal(err)
	}
	return ProofCheck{File: path, PublicKey: f.nodePublic}
}

func (policy ReceiptPolicy) Verify(receiptWire, delegationWire []byte, now time.Time) (release.VerifiedBinary, error) {
	if len(policy.Roots) == 0 {
		return release.VerifiedBinary{}, fmt.Errorf("%w: no release trust roots", ErrInvalid)
	}
	envelope, err := trust.DecodeEnvelope(receiptWire)
	if err != nil {
		return release.VerifiedBinary{}, err
	}
	var verified release.VerifiedBinary
	switch envelope.Scope.Domain {
	case release.BinaryDomain:
		return release.VerifiedBinary{}, fmt.Errorf("%w: self-update requires a region-qualified update receipt", release.ErrProductionQualification)
	case release.UpdateReceiptDomain:
		verified, err = release.VerifyQualifiedBinaryUpdateCurrent(receiptWire, delegationWire, policy.Roots,
			release.UpdateExpectation{Environment: policy.Environment, Cell: policy.Cell, Architecture: policy.Architecture}, now)
	default:
		return release.VerifiedBinary{}, fmt.Errorf("%w: receipt domain %q", ErrInvalid, envelope.Scope.Domain)
	}
	if err != nil {
		return release.VerifiedBinary{}, err
	}
	if !verified.IsVerified() || verified.Receipt().GOARCH != policy.Architecture {
		return release.VerifiedBinary{}, fmt.Errorf("%w: receipt architecture differs from this node", release.ErrExpectationMismatch)
	}
	return verified, nil
}

func Stage(layout Layout, source io.Reader, receiptWire, delegationWire []byte, verifier Verifier, now time.Time) (string, error) {
	if source == nil || verifier == nil {
		return "", fmt.Errorf("%w: stage source and verifier are required", ErrInvalid)
	}
	verified, err := verifier.Verify(receiptWire, delegationWire, now)
	if err != nil {
		return "", fmt.Errorf("verify release receipt: %w", err)
	}
	receipt := verified.Receipt()
	if knownBad, err := layout.KnownBad(); err != nil {
		return "", err
	} else if knownBad[receipt.SHA256] {
		return "", ErrKnownBad
	}
	if err := layout.ensureDirs(); err != nil {
		return "", err
	}
	if _, err := os.Lstat(layout.ReleaseDir(receipt.SHA256)); err == nil {
		if err := layout.VerifyRelease(receipt.SHA256); err != nil {
			return "", err
		}
		return receipt.SHA256, nil
	}
	if err := layout.install(source, receipt.SHA256, receipt.Bytes, map[string][]byte{
		receiptFile: receiptWire, delegationFile: delegationWire,
	}); err != nil {
		return "", err
	}
	return receipt.SHA256, nil
}

func Seed(layout Layout, bakedBinary string) (string, error) {
	if err := layout.ensureDirs(); err != nil {
		return "", err
	}
	current, err := layout.Current()
	if err != nil || current != "" {
		return current, err
	}
	file, err := os.Open(bakedBinary)
	if err != nil {
		return "", err
	}
	defer file.Close()
	info, err := file.Stat()
	if err != nil || !info.Mode().IsRegular() || info.Size() <= 0 || info.Size() > MaxBinaryBytes {
		return "", fmt.Errorf("%w: baked binary", ErrInvalid)
	}
	digest, _, err := hashFile(bakedBinary)
	if err != nil {
		return "", err
	}
	if _, err := os.Lstat(layout.ReleaseDir(digest)); errors.Is(err, os.ErrNotExist) {
		if err := layout.install(file, digest, info.Size(), map[string][]byte{bakedMarkerFile: []byte(bakedBinary + "\n")}); err != nil {
			return "", err
		}
	}
	if err := layout.VerifyRelease(digest); err != nil {
		return "", err
	}
	return digest, layout.flipCurrent(digest)
}

func (layout Layout) install(source io.Reader, digest string, size int64, metadata map[string][]byte) error {
	if !digestRE.MatchString(digest) || size <= 0 || size > MaxBinaryBytes {
		return fmt.Errorf("%w: release identity", ErrInvalid)
	}
	temporary, err := os.MkdirTemp(layout.releasesPath(), ".staging-")
	if err != nil {
		return err
	}
	defer os.RemoveAll(temporary)
	if err := os.Chmod(temporary, 0o755); err != nil {
		return err
	}
	binary, err := os.OpenFile(filepath.Join(temporary, BinaryName), os.O_CREATE|os.O_EXCL|os.O_WRONLY, 0o500)
	if err != nil {
		return err
	}
	hash := sha256.New()
	written, copyErr := io.Copy(io.MultiWriter(binary, hash), io.LimitReader(source, size+1))
	if copyErr == nil {
		copyErr = binary.Chmod(0o555)
	}
	if copyErr == nil {
		copyErr = binary.Sync()
	}
	if closeErr := binary.Close(); copyErr == nil {
		copyErr = closeErr
	}
	if copyErr != nil {
		return copyErr
	}
	if written != size || hex.EncodeToString(hash.Sum(nil)) != digest {
		return fmt.Errorf("%w: staged binary differs from its signed size or digest", ErrInvalid)
	}
	for name, data := range metadata {
		if err := writeSyncedFile(filepath.Join(temporary, name), data, 0o444); err != nil {
			return err
		}
	}
	if err := syncDir(temporary); err != nil {
		return err
	}
	if err := os.Rename(temporary, layout.ReleaseDir(digest)); err != nil {
		return err
	}
	if err := syncDir(layout.releasesPath()); err != nil {
		return err
	}
	return layout.VerifyRelease(digest)
}

func writeSyncedFile(path string, data []byte, mode os.FileMode) error {
	file, err := os.OpenFile(path, os.O_CREATE|os.O_EXCL|os.O_WRONLY, mode)
	if err != nil {
		return err
	}
	_, err = file.Write(data)
	if err == nil {
		err = file.Chmod(mode)
	}
	if err == nil {
		err = file.Sync()
	}
	if closeErr := file.Close(); err == nil {
		err = closeErr
	}
	return err
}

func (layout Layout) releasesPath() string { return filepath.Join(layout.Root, releasesDir) }
func (layout Layout) currentPath() string  { return filepath.Join(layout.Root, currentLink) }
func (layout Layout) activationPath() string {
	return filepath.Join(layout.Root, activationFile)
}
func (layout Layout) knownBadPath() string { return filepath.Join(layout.Root, knownBadFile) }

// ReleaseDir is the directory of one staged release.
func (layout Layout) ReleaseDir(digest string) string {
	return filepath.Join(layout.releasesPath(), digest)
}

// BinaryPath is the executable of one staged release.
func (layout Layout) BinaryPath(digest string) string {
	return filepath.Join(layout.ReleaseDir(digest), BinaryName)
}

// CurrentExecutable is the path the systemd ExecStart line runs.
func (layout Layout) CurrentExecutable() string {
	return filepath.Join(layout.currentPath(), BinaryName)
}

func (layout Layout) ensureDirs() error {
	if err := layout.validate(); err != nil {
		return err
	}
	for _, path := range []string{layout.Root, layout.releasesPath()} {
		// The units run with UMask=0077; set the mode explicitly so the
		// unprivileged controller can traverse to its binary.
		if err := os.Mkdir(path, 0o755); err == nil {
			if err := os.Chmod(path, 0o755); err != nil {
				return err
			}
		} else if !errors.Is(err, os.ErrExist) {
			return err
		}
		if err := layout.checkOwned(path, true); err != nil {
			return err
		}
	}
	return nil
}

func (layout Layout) checkOwned(path string, directory bool) error {
	info, err := os.Lstat(path)
	if err != nil {
		return err
	}
	stat, ok := info.Sys().(*syscall.Stat_t)
	if !ok || int(stat.Uid) != layout.Owner || info.Mode().Perm()&0o022 != 0 ||
		directory && !info.IsDir() || !directory && !info.Mode().IsRegular() {
		return fmt.Errorf("%w: %s", ErrUnsafe, path)
	}
	return nil
}

func (layout Layout) readLink(name string) (string, error) {
	if err := layout.validate(); err != nil {
		return "", err
	}
	target, err := os.Readlink(filepath.Join(layout.Root, name))
	if errors.Is(err, os.ErrNotExist) {
		return "", nil
	}
	if err != nil {
		return "", err
	}
	digest, ok := strings.CutPrefix(target, releasesDir+"/")
	if !ok || !digestRE.MatchString(digest) {
		return "", fmt.Errorf("%w: %s link target %q", ErrUnsafe, name, target)
	}
	return digest, nil
}

func (layout Layout) Delegate() (string, error) {
	digest, err := layout.KnownGood()
	if err != nil || digest == "" {
		return "", err
	}
	if _, err := os.Lstat(filepath.Join(layout.ReleaseDir(digest), bakedMarkerFile)); err == nil {
		return "", nil
	}
	knownBad, err := layout.KnownBad()
	if err != nil || knownBad[digest] {
		return "", err
	}
	return digest, layout.VerifyRelease(digest)
}

func (layout Layout) VerifyRelease(digest string) error {
	if !digestRE.MatchString(digest) {
		return fmt.Errorf("%w: release digest", ErrInvalid)
	}
	for _, path := range []string{layout.Root, layout.releasesPath(), layout.ReleaseDir(digest)} {
		if err := layout.checkOwned(path, true); err != nil {
			return err
		}
	}
	path := layout.BinaryPath(digest)
	if err := layout.checkOwned(path, false); err != nil {
		return err
	}
	observed, _, err := hashFile(path)
	if err != nil {
		return err
	}
	if observed != digest {
		return fmt.Errorf("%w: release %s bytes changed", ErrUnsafe, digest)
	}
	return nil
}

func (layout Layout) flipLink(name, digest string) error {
	temporary := filepath.Join(layout.Root, "."+name+"-"+digest[:16])
	_ = os.Remove(temporary)
	if err := os.Symlink(releasesDir+"/"+digest, temporary); err != nil {
		return err
	}
	if err := os.Rename(temporary, filepath.Join(layout.Root, name)); err != nil {
		_ = os.Remove(temporary)
		return err
	}
	return syncDir(layout.Root)
}

func hashFile(path string) (string, int64, error) {
	file, err := os.Open(path)
	if err != nil {
		return "", 0, err
	}
	defer file.Close()
	hash := sha256.New()
	size, err := io.Copy(hash, io.LimitReader(file, MaxBinaryBytes+1))
	if err != nil {
		return "", 0, err
	}
	if size > MaxBinaryBytes {
		return "", 0, fmt.Errorf("%w: binary exceeds %d bytes", ErrInvalid, MaxBinaryBytes)
	}
	return hex.EncodeToString(hash.Sum(nil)), size, nil
}

func syncDir(path string) error {
	directory, err := os.Open(path)
	if err != nil {
		return err
	}
	defer directory.Close()
	return directory.Sync()
}

func writeFileAtomic(path string, data []byte, mode os.FileMode) error {
	directory := filepath.Dir(path)
	file, err := os.CreateTemp(directory, "."+filepath.Base(path)+"-*")
	if err != nil {
		return err
	}
	name := file.Name()
	defer os.Remove(name)
	if _, err := file.Write(data); err != nil {
		file.Close()
		return err
	}
	if err := file.Chmod(mode); err != nil {
		file.Close()
		return err
	}
	if err := file.Sync(); err != nil {
		file.Close()
		return err
	}
	if err := file.Close(); err != nil {
		return err
	}
	if err := os.Rename(name, path); err != nil {
		return err
	}
	return syncDir(directory)
}

func readBounded(path string, maximum int64) ([]byte, error) {
	fd, err := syscall.Open(path, syscall.O_RDONLY|syscall.O_CLOEXEC|syscall.O_NOFOLLOW|syscall.O_NONBLOCK, 0)
	if err != nil {
		return nil, &os.PathError{Op: "open", Path: path, Err: err}
	}
	file := os.NewFile(uintptr(fd), path)
	defer file.Close()
	info, err := file.Stat()
	if err != nil {
		return nil, err
	}
	if !info.Mode().IsRegular() {
		return nil, fmt.Errorf("%w: %s is not a regular file", ErrInvalid, path)
	}
	data, err := io.ReadAll(io.LimitReader(file, maximum+1))
	if err != nil {
		return nil, err
	}
	if int64(len(data)) > maximum {
		return nil, fmt.Errorf("%w: %s is too large", ErrInvalid, path)
	}
	return data, nil
}

func (activation Activation) validate() error {
	if activation.Schema != ActivationSchema || !digestRE.MatchString(activation.Target) ||
		!digestRE.MatchString(activation.Previous) || activation.Target == activation.Previous ||
		!entityid.Valid(activation.ActivationID) || !unitRE.MatchString(activation.Unit) ||
		activation.ActivatedAt.IsZero() || !activation.Deadline.After(activation.ActivatedAt) ||
		activation.Deadline.Sub(activation.ActivatedAt) > MaxProofWindow {
		return fmt.Errorf("%w: activation record", ErrInvalid)
	}
	return nil
}

func (layout Layout) Pending() (Activation, bool, error) {
	data, exists, err := layout.pendingRecord()
	if err != nil || !exists {
		return Activation{}, false, err
	}
	activation, err := decodeActivation(data)
	if err != nil {
		return Activation{}, false, err
	}
	return activation, true, nil
}

func (layout Layout) RecoveryActivation() (Activation, error) {
	data, exists, err := layout.pendingRecord()
	if err != nil || !exists {
		return Activation{}, errors.Join(ErrInvalid, err)
	}
	if _, err := decodeActivation(data); !errors.Is(err, ErrUnreadableActivation) {
		return Activation{}, ErrInvalid
	}
	var pins struct {
		Target   string `json:"target"`
		Previous string `json:"previous"`
		Unit     string `json:"unit"`
	}
	if err := json.Unmarshal(data, &pins); err != nil ||
		!digestRE.MatchString(pins.Target) || !digestRE.MatchString(pins.Previous) ||
		pins.Target == pins.Previous || !unitRE.MatchString(pins.Unit) {
		return Activation{}, errors.Join(ErrUnreadableActivation, err)
	}
	return Activation{Target: pins.Target, Previous: pins.Previous, Unit: pins.Unit}, nil
}

func (layout Layout) pendingRecord() ([]byte, bool, error) {
	if err := layout.checkOwned(layout.activationPath(), false); errors.Is(err, os.ErrNotExist) {
		return nil, false, nil
	} else if err != nil {
		return nil, false, err
	}
	data, err := readBounded(layout.activationPath(), maxStateBytes)
	if err != nil {
		return nil, false, err
	}
	return data, true, nil
}

func decodeActivation(data []byte) (Activation, error) {
	var activation Activation
	if err := protocol.DecodeStrict(data, &activation, maxStateBytes); err != nil {
		return Activation{}, fmt.Errorf("%w: activation record: %w", ErrUnreadableActivation, err)
	}
	if err := activation.validate(); err != nil {
		return Activation{}, fmt.Errorf("%w: %w", ErrUnreadableActivation, err)
	}
	return activation, nil
}

func Activate(layout Layout, digest, unit string, now time.Time, window time.Duration) (Activation, error) {
	if window < MinProofWindow || window > MaxProofWindow || !unitRE.MatchString(unit) || now.IsZero() {
		return Activation{}, fmt.Errorf("%w: activation unit or proof window", ErrInvalid)
	}
	// An interrupted rollout restore is finished before the selection
	// changes again, so its recovery can never overwrite this activation.
	if err := layout.finishRestores(); err != nil {
		return Activation{}, err
	}
	if pending, exists, err := layout.Pending(); err != nil {
		return Activation{}, err
	} else if exists {
		if pending.Target == digest && pending.Unit == unit {
			// A retry passes the same gates as a fresh activation: a crash
			// after a rollback marked the target known bad must not
			// re-activate it, and unverified bytes never become current.
			if !now.Before(pending.Deadline) {
				return Activation{}, fmt.Errorf("%w: activation %s passed its deadline; the watchdog resolves it", ErrInvalid, pending.ActivationID)
			}
			if knownBad, err := layout.KnownBad(); err != nil {
				return Activation{}, err
			} else if knownBad[digest] {
				return Activation{}, ErrKnownBad
			}
			if err := layout.VerifyRelease(digest); err != nil {
				return Activation{}, err
			}
			return pending, layout.flipCurrent(digest)
		}
		return Activation{}, fmt.Errorf("%w: activation %s is still pending", ErrInvalid, pending.ActivationID)
	}
	if knownBad, err := layout.KnownBad(); err != nil {
		return Activation{}, err
	} else if knownBad[digest] {
		return Activation{}, ErrKnownBad
	}
	previous, err := layout.Current()
	if err != nil {
		return Activation{}, err
	}
	if previous == "" {
		return Activation{}, fmt.Errorf("%w: seed the baked release before activating another", ErrInvalid)
	}
	if previous == digest {
		return Activation{}, fmt.Errorf("%w: release is already current", ErrInvalid)
	}
	for _, release := range []string{previous, digest} {
		if err := layout.VerifyRelease(release); err != nil {
			return Activation{}, err
		}
	}

	activation := Activation{
		Schema: ActivationSchema, ActivationID: entityid.NewAt(now), Unit: unit,
		Target: digest, Previous: previous, ActivatedAt: now.UTC(), Deadline: now.UTC().Add(window),
	}
	encoded, err := protocol.EncodeJSON(activation)
	if err != nil {
		return Activation{}, err
	}
	if err := writeFileAtomic(layout.activationPath(), encoded, 0o644); err != nil {
		return Activation{}, err
	}
	if err := layout.flipCurrent(digest); err != nil {
		return activation, err
	}
	recordActivation(activation)
	return activation, nil
}

func (layout Layout) KnownBad() (map[string]bool, error) {
	data, err := readBounded(layout.knownBadPath(), maxStateBytes)
	if errors.Is(err, os.ErrNotExist) {
		return map[string]bool{}, nil
	}
	if err != nil {
		return nil, err
	}
	var state knownBadState
	if err := protocol.DecodeStrict(data, &state, maxStateBytes); err != nil {
		return nil, err
	}
	known := make(map[string]bool, len(state.Digests))
	for _, digest := range state.Digests {
		if !digestRE.MatchString(digest) {
			return nil, fmt.Errorf("%w: known-bad digest", ErrInvalid)
		}
		known[digest] = true
	}
	return known, nil
}

func (layout Layout) markKnownBad(digest string) error {
	data, err := readBounded(layout.knownBadPath(), maxStateBytes)
	var state knownBadState
	switch {
	case errors.Is(err, os.ErrNotExist):
	case err != nil:
		return err
	default:
		if err := protocol.DecodeStrict(data, &state, maxStateBytes); err != nil {
			return err
		}
	}
	if slices.Contains(state.Digests, digest) {
		return nil
	}
	state.Digests = append(state.Digests, digest)
	if len(state.Digests) > maxKnownBad {
		state.Digests = state.Digests[len(state.Digests)-maxKnownBad:]
	}
	encoded, err := protocol.EncodeJSON(state)
	if err != nil {
		return err
	}
	return writeFileAtomic(layout.knownBadPath(), encoded, 0o644)
}

func Watch(layout Layout, unit string, proof ProofCheck, now time.Time) (Outcome, Activation, error) {
	// A rollout restore interrupted before its link moved is finished
	// first, so neither the watchdog's restart nor the unit's start ever
	// runs the release the restore rejected.
	if err := layout.finishRestores(); err != nil {
		return OutcomeIdle, Activation{}, fmt.Errorf("finish interrupted restore: %w", err)
	}
	activation, pending, err := layout.Pending()
	if errors.Is(err, ErrUnreadableActivation) {
		return layout.resolveUnreadable(err)
	}
	if err != nil || !pending {
		return OutcomeIdle, Activation{}, err
	}
	if activation.Unit != unit {
		// Another unit's watchdog resolves this activation. Once it is long
		// past its deadline no functioning watchdog is left to do so (a
		// mistyped unit, or a unit without the drop-ins): roll it back so it
		// cannot block every later activation on this node.
		if now.Before(activation.Deadline.Add(OrphanedActivationGrace)) {
			return OutcomePending, activation, nil
		}
		slog.Warn("self-update activation of an unwatched unit expired; rolling back",
			"activation", activation.ActivationID, "unit", activation.Unit)
		if err := layout.rollback(activation); err != nil {
			return OutcomeRolledBack, activation, err
		}
		recordResolution(activation, OutcomeRolledBack)
		return OutcomeRolledBack, activation, nil
	}
	// rollback marks the target known bad before it moves the link and
	// removes the record. A known-bad target therefore means a rollback was
	// committed and interrupted: finish it instead of accepting a proof.
	knownBad, err := layout.KnownBad()
	if err != nil {
		return OutcomePending, activation, err
	}
	if knownBad[activation.Target] {
		slog.Warn("self-update rollback was interrupted; finishing it", "activation", activation.ActivationID)
		if err := layout.rollback(activation); err != nil {
			return OutcomeRolledBack, activation, err
		}
		recordResolution(activation, OutcomeRolledBack)
		return OutcomeRolledBack, activation, nil
	}
	// Only a target that is actually selected can be confirmed. Otherwise
	// the activation stays pending until its deadline rolls it back.
	current, err := layout.Current()
	if err != nil {
		return OutcomePending, activation, err
	}
	targetErr := layout.VerifyRelease(activation.Target)
	if targetErr == nil && current == activation.Target && len(proof.PublicKey) == ed25519.PublicKeySize {
		if wire, err := readProof(proof.File); err == nil {
			if verified, err := VerifyVersionProof(wire, proof.PublicKey, activation, now); err == nil && !processRunning(verified.ProcessID) {
				// A proof only confirms while the process that signed it
				// still runs: one that crashed right after proving must not
				// confirm the activation at the next check.
				slog.Warn("self-update version proof process is gone", "activation", activation.ActivationID, "pid", verified.ProcessID)
			} else if err == nil {
				if err := layout.rememberConfirmed(activation.Target); err != nil {
					return OutcomePending, activation, err
				}
				// The confirmed release runs the image's root steps from
				// now on (Delegate).
				if err := layout.flipLink(knownGoodLink, activation.Target); err != nil {
					return OutcomePending, activation, err
				}
				if err := os.Remove(layout.activationPath()); err != nil {
					return OutcomePending, activation, err
				}
				if err := syncDir(layout.Root); err != nil {
					return OutcomeConfirmed, activation, err
				}
				recordResolution(activation, OutcomeConfirmed)
				return OutcomeConfirmed, activation, nil
			} else {
				slog.Warn("self-update version proof rejected", "activation", activation.ActivationID, "error", err)
			}
		} else if !errors.Is(err, os.ErrNotExist) {
			slog.Warn("self-update version proof unreadable", "activation", activation.ActivationID, "error", err)
		}
	}
	if targetErr == nil && now.Before(activation.Deadline) {
		return OutcomePending, activation, nil
	}
	if err := layout.rollback(activation); err != nil {
		return OutcomeRolledBack, activation, err
	}
	recordResolution(activation, OutcomeRolledBack)
	return OutcomeRolledBack, activation, nil
}

var processRunning = func(pid int64) bool {
	if pid <= 0 || pid > math.MaxInt32 {
		return false
	}
	err := syscall.Kill(int(pid), 0)
	return err == nil || errors.Is(err, syscall.EPERM)
}

func (layout Layout) resolveUnreadable(cause error) (Outcome, Activation, error) {
	_, exists, err := layout.pendingRecord()
	if err != nil || !exists {
		return OutcomeIdle, Activation{}, err
	}
	outcome := OutcomeIdle
	activation, recoveryErr := layout.RecoveryActivation()
	if recoveryErr == nil && layout.VerifyRelease(activation.Previous) == nil {
		current, err := layout.Current()
		if err != nil {
			return OutcomePending, activation, err
		}
		if current != activation.Target && current != activation.Previous {
			return OutcomePending, activation, fmt.Errorf("%w: unreadable activation does not own current selection", ErrInvalid)
		}
		if err := layout.markKnownBad(activation.Target); err != nil {
			return OutcomePending, activation, err
		}
		if current == activation.Target {
			if err := layout.flipCurrent(activation.Previous); err != nil {
				return OutcomePending, activation, err
			}
		}
		if err := layout.markRestartPending(activation.Unit); err != nil {
			return OutcomePending, activation, err
		}
		outcome = OutcomeRolledBack
	}
	quarantine := layout.activationPath() + ".unreadable-" + time.Now().UTC().Format("20060102T150405.000000000Z")
	if err := os.Rename(layout.activationPath(), quarantine); err != nil {
		return OutcomePending, activation, err
	}
	slog.Warn("self-update activation record was unreadable and was moved aside",
		"path", quarantine, "outcome", outcome, "error", cause)
	return outcome, activation, syncDir(layout.Root)
}

func (layout Layout) rollback(activation Activation) error {
	if err := layout.markKnownBad(activation.Target); err != nil {
		return err
	}
	if err := layout.VerifyRelease(activation.Previous); err != nil {
		return fmt.Errorf("previous release cannot be restored: %w", err)
	}
	if err := layout.flipCurrent(activation.Previous); err != nil {
		return err
	}
	// The rejected process may still run: keep a restart obligation that
	// outlives this invocation before the activation record goes away.
	if err := layout.markRestartPending(activation.Unit); err != nil {
		return err
	}
	if err := os.Remove(layout.activationPath()); err != nil {
		return err
	}
	return syncDir(layout.Root)
}

func Prepare(layout Layout, unit, bakedBinary string, proof ProofCheck, now time.Time) (Outcome, error) {
	if _, err := Seed(layout, bakedBinary); err != nil {
		return OutcomeIdle, fmt.Errorf("seed baked release: %w", err)
	}
	// Prepare runs while the unit (re)starts, so the process behind any
	// existing proof is gone: a proof never confirms across a restart. The
	// new process proves itself again for the watchdog; prepare only
	// resolves expired, unwatched or unreadable activations; its proof
	// argument is accepted for the drop-in's flags and not used to confirm.
	outcome, activation, err := Watch(layout, unit, ProofCheck{}, now)
	if err != nil {
		return outcome, err
	}
	// The unit is starting now, so any restart a rollback still owed it is
	// being served by this start.
	if unitRE.MatchString(unit) {
		if err := layout.ClearRestartPending(unit); err != nil {
			return outcome, err
		}
	}
	current, err := layout.Current()
	if err != nil {
		return outcome, err
	}
	// The units on a node share the current link. A unit never starts the
	// unconfirmed target of another unit's activation: it cannot prove it,
	// and that activation's rollback does not restart it. Its restart policy
	// retries once the activation is resolved.
	if outcome == OutcomePending && activation.Unit != unit && current == activation.Target {
		return outcome, fmt.Errorf("%w: %s waits for the pending activation of %s", ErrInvalid, unit, activation.Unit)
	}
	if err := layout.VerifyRelease(current); err != nil {
		return outcome, fmt.Errorf("current release does not verify: %w", err)
	}
	if removed, err := layout.PruneReleases(now); err != nil {
		slog.Warn("self-update release pruning failed", "error", err)
	} else if len(removed) > 0 {
		slog.Info("self-update pruned settled releases", "releases", removed)
	}
	return outcome, nil
}

func Backstop(layout Layout, now time.Time) (Outcome, Activation, error) {
	activation, pending, err := layout.Pending()
	if errors.Is(err, ErrUnreadableActivation) {
		return OutcomeIdle, Activation{}, nil
	}
	if err != nil || !pending {
		return OutcomeIdle, Activation{}, err
	}
	bad, err := layout.KnownBad()
	if err != nil {
		return OutcomePending, activation, err
	}
	if !bad[activation.Target] && layout.VerifyRelease(activation.Target) == nil && now.Before(activation.Deadline.Add(OrphanedActivationGrace)) {
		return OutcomePending, activation, nil
	}
	slog.Warn("self-update activation is damaged or outlived its deadline; rolling back",
		"activation", activation.ActivationID, "unit", activation.Unit)
	if err := layout.rollback(activation); err != nil {
		return OutcomeRolledBack, activation, err
	}
	recordResolution(activation, OutcomeRolledBack)
	return OutcomeRolledBack, activation, nil
}

func (layout Layout) PruneReleases(now time.Time) ([]string, error) {
	current, err := layout.Current()
	if err != nil {
		return nil, err
	}
	if current == "" {
		return nil, nil
	}
	keep := map[string]bool{current: true}
	if known, err := layout.KnownGood(); err != nil {
		return nil, err
	} else if known != "" {
		keep[known] = true
	}
	confirmed, err := layout.ConfirmedReleases()
	if err != nil {
		return nil, err
	}
	for _, digest := range confirmed {
		keep[digest] = true
	}
	activation, pending, err := layout.Pending()
	if err != nil {
		return nil, err
	}
	if pending {
		keep[activation.Target], keep[activation.Previous] = true, true
	}
	knownBad, err := layout.KnownBad()
	if err != nil {
		return nil, err
	}
	entries, err := os.ReadDir(layout.releasesPath())
	if err != nil {
		return nil, err
	}
	var removed []string
	for _, entry := range entries {
		digest := entry.Name()
		if !digestRE.MatchString(digest) || keep[digest] {
			continue
		}
		directory := layout.ReleaseDir(digest)
		info, err := os.Lstat(directory)
		if err != nil || !info.IsDir() {
			continue
		}
		if _, err := os.Lstat(filepath.Join(directory, bakedMarkerFile)); err == nil {
			continue
		}
		if !knownBad[digest] && now.Sub(info.ModTime()) < StagedReleaseRetention {
			continue
		}
		if err := layout.checkOwned(directory, true); err != nil {
			return removed, err
		}
		if err := os.RemoveAll(directory); err != nil {
			return removed, err
		}
		removed = append(removed, digest)
	}
	if len(removed) > 0 {
		return removed, syncDir(layout.releasesPath())
	}
	return removed, nil
}

func (layout Layout) restartMarkerPath(unit string) string {
	return filepath.Join(layout.Root, restartMarkerPrefix+unit)
}

func (layout Layout) markRestartPending(unit string) error {
	if !unitRE.MatchString(unit) {
		return fmt.Errorf("%w: unit", ErrInvalid)
	}
	return writeFileAtomic(layout.restartMarkerPath(unit), []byte(unit+"\n"), 0o644)
}

func (layout Layout) RestartPending(unit string) (bool, error) {
	if !unitRE.MatchString(unit) {
		return false, fmt.Errorf("%w: unit", ErrInvalid)
	}
	err := layout.checkOwned(layout.restartMarkerPath(unit), false)
	if errors.Is(err, os.ErrNotExist) {
		return false, nil
	}
	return err == nil, err
}

func (layout Layout) ClearRestartPending(unit string) error {
	if !unitRE.MatchString(unit) {
		return fmt.Errorf("%w: unit", ErrInvalid)
	}
	if err := os.Remove(layout.restartMarkerPath(unit)); err != nil && !errors.Is(err, os.ErrNotExist) {
		return err
	}
	return nil
}

func (layout Layout) ConfirmedReleases() ([]string, error) {
	if err := layout.validate(); err != nil {
		return nil, err
	}
	path := filepath.Join(layout.Root, confirmedReleasesFile)
	if err := layout.checkOwned(path, false); errors.Is(err, os.ErrNotExist) {
		return nil, nil
	} else if err != nil {
		return nil, err
	}
	data, err := readBounded(path, maxStateBytes)
	if err != nil {
		return nil, err
	}
	var history confirmedReleases
	if err := protocol.DecodeStrict(data, &history, maxStateBytes); err != nil {
		return nil, err
	}
	if history.Schema != confirmedReleasesSchema || len(history.Releases) > ConfirmedReleaseHistory {
		return nil, fmt.Errorf("%w: confirmed release history", ErrInvalid)
	}
	seen := make(map[string]bool, len(history.Releases))
	for _, digest := range history.Releases {
		if !digestRE.MatchString(digest) || seen[digest] {
			return nil, fmt.Errorf("%w: confirmed release history", ErrInvalid)
		}
		seen[digest] = true
	}
	bad, err := layout.KnownBad()
	if err != nil {
		return nil, err
	}
	return slices.DeleteFunc(history.Releases, func(digest string) bool { return bad[digest] }), nil
}

func (layout Layout) rememberConfirmed(digest string) error {
	history, err := layout.ConfirmedReleases()
	if err != nil {
		return err
	}
	if err := layout.VerifyRelease(digest); err != nil {
		return err
	}
	history = slices.DeleteFunc(history, func(previous string) bool { return previous == digest })
	history = append([]string{digest}, history...)
	history = history[:min(len(history), ConfirmedReleaseHistory)]
	data, err := protocol.EncodeJSON(confirmedReleases{Schema: confirmedReleasesSchema, Releases: history})
	if err != nil {
		return err
	}
	return writeFileAtomic(filepath.Join(layout.Root, confirmedReleasesFile), data, 0o644)
}

func SignVersionProof(proof VersionProof, privateKey ed25519.PrivateKey, now time.Time) ([]byte, error) {
	if proof.Schema != ProofSchema || !entityid.Valid(proof.ActivationID) || !unitRE.MatchString(proof.Unit) ||
		!digestRE.MatchString(proof.BinarySHA256) || proof.ProcessID <= 0 || proof.ObservedAt.IsZero() {
		return nil, fmt.Errorf("%w: version proof", ErrInvalid)
	}
	payload, err := trust.EncodePayload(proof)
	if err != nil {
		return nil, err
	}
	envelope, err := trust.Sign(payload, proofScope(proof.ActivationID, proof.BinarySHA256), now, now.Add(ProofLifetime), privateKey)
	if err != nil {
		return nil, err
	}
	return trust.EncodeEnvelope(envelope)
}

func VerifyVersionProof(wire []byte, publicKey ed25519.PublicKey, activation Activation, now time.Time) (VersionProof, error) {
	if err := activation.validate(); err != nil {
		return VersionProof{}, err
	}
	keys, err := trust.ParseKeyring(publicKey)
	if err != nil {
		return VersionProof{}, err
	}
	envelope, err := trust.DecodeEnvelope(wire)
	if err != nil {
		return VersionProof{}, err
	}
	payload, err := trust.VerifyCurrent(envelope, proofScope(activation.ActivationID, activation.Target), keys, now,
		trust.Policy{MaxLifetime: ProofLifetime, ClockSkew: proofClock})
	if err != nil {
		return VersionProof{}, err
	}
	var proof VersionProof
	if err := protocol.DecodeStrict(payload, &proof, maxStateBytes); err != nil {
		return VersionProof{}, err
	}
	if proof.Schema != ProofSchema || proof.ActivationID != activation.ActivationID || proof.Unit != activation.Unit ||
		proof.BinarySHA256 != activation.Target || proof.ProcessID <= 0 ||
		envelope.IssuedAt.Before(activation.ActivatedAt.Truncate(time.Second)) || proof.ObservedAt.Before(activation.ActivatedAt) {
		return VersionProof{}, fmt.Errorf("%w: version proof is not fresh for this activation", ErrInvalid)
	}
	// A process that became ready only after its proof window must not be
	// confirmed by a late check. A check after the deadline still accepts a
	// proof produced in time.
	if envelope.IssuedAt.After(activation.Deadline) || proof.ObservedAt.After(activation.Deadline) {
		return VersionProof{}, fmt.Errorf("%w: version proof was produced after the activation deadline", ErrInvalid)
	}
	return proof, nil
}

func readProof(path string) ([]byte, error) {
	if path == "" {
		return nil, os.ErrNotExist
	}
	wire, err := readBounded(path, trust.MaxEnvelopeBytes)
	if err != nil {
		return nil, err
	}
	if len(wire) == 0 {
		return nil, errors.New("empty version proof")
	}
	return wire, nil
}

func Restore(layout Layout, digest, rejected, unit string) (bool, error) {
	if !digestRE.MatchString(digest) || !digestRE.MatchString(rejected) || digest == rejected || !unitRE.MatchString(unit) {
		return false, fmt.Errorf("%w: restore target", ErrInvalid)
	}
	if err := layout.finishRestores(); err != nil {
		return false, err
	}
	if knownBad, err := layout.KnownBad(); err != nil {
		return false, err
	} else if knownBad[digest] {
		return false, ErrKnownBad
	}
	if err := layout.VerifyRelease(digest); err != nil {
		return false, err
	}
	activation, pending, err := layout.Pending()
	if err != nil {
		return false, err
	}
	if pending {
		if activation.Unit != unit || activation.Target != rejected || activation.Previous != digest {
			return false, fmt.Errorf("%w: activation %s is pending for another release", ErrInvalid, activation.ActivationID)
		}
		if err := layout.rollback(activation); err != nil {
			return true, err
		}
		recordResolution(activation, OutcomeRolledBack)
		return true, nil
	}
	current, err := layout.Current()
	if err != nil {
		return false, err
	}
	switch current {
	case digest:
		// The unit never left digest, but the rollout rejected the other
		// release: this node must refuse it from now on too. Nothing
		// changed the selection, so no restart is owed.
		return false, layout.markKnownBad(rejected)
	case rejected:
	default:
		return false, fmt.Errorf("%w: the current release is neither the restore target nor the rejected release", ErrInvalid)
	}
	// There is no activation record to recover an interrupted restore
	// from, so a durable intent names the target first; finishRestore
	// completes the switch from it at any later point.
	intent, err := protocol.EncodeJSON(RestoreIntent{Schema: restoreIntentSchema, Unit: unit, Target: digest, Rejected: rejected})
	if err != nil {
		return false, err
	}
	if err := writeFileAtomic(layout.restoreIntentPath(unit), intent, 0o644); err != nil {
		return false, err
	}
	if err := layout.finishRestore(unit); err != nil {
		return true, err
	}
	decisionlog.Record(context.Background(), decisionlog.Decision{
		Actor:   decisionlog.Actor{Slice: "selfupdate"},
		Kind:    decisionlog.KindRollback,
		Subject: memberSubject(unit),
		Summary: "Restored release " + shortDigest(digest) + " on " + unit,
		Reason:  "A rollout rolled back the release this unit ran; that release is now known bad on this node.",
		Rule:    "selfupdate.restore",
		Status:  decisionlog.StatusRolledBack,
		Attrs:   map[string]string{"version": digest, "rejected": rejected},
	})
	return true, nil
}

func (layout Layout) finishRestores() error {
	intents, err := layout.PendingRestores()
	if err != nil {
		return err
	}
	for _, intent := range intents {
		if err := layout.finishRestore(intent.Unit); err != nil {
			return err
		}
	}
	return nil
}

func (layout Layout) PendingRestores() ([]RestoreIntent, error) {
	if err := layout.validate(); err != nil {
		return nil, err
	}
	if err := layout.checkOwned(layout.Root, true); errors.Is(err, os.ErrNotExist) {
		return nil, nil
	} else if err != nil {
		return nil, err
	}
	entries, err := os.ReadDir(layout.Root)
	if err != nil {
		return nil, err
	}
	var intents []RestoreIntent
	for _, entry := range entries {
		unit, ok := strings.CutPrefix(entry.Name(), restoreIntentPrefix)
		if !ok {
			continue
		}
		unit, ok = strings.CutSuffix(unit, ".json")
		if !ok || !unitRE.MatchString(unit) {
			return nil, fmt.Errorf("%w: restore intent %q", ErrUnsafe, entry.Name())
		}
		if _, pending, err := layout.Pending(); err != nil {
			return nil, err
		} else if pending {
			return nil, fmt.Errorf("%w: restore intent of %s next to a pending activation", ErrUnsafe, unit)
		}
		intent, err := layout.readRestoreIntent(unit)
		if err != nil {
			return nil, err
		}
		intents = append(intents, intent)
	}
	return intents, nil
}

func (layout Layout) readRestoreIntent(unit string) (RestoreIntent, error) {
	path := layout.restoreIntentPath(unit)
	if err := layout.checkOwned(path, false); err != nil {
		return RestoreIntent{}, err
	}
	data, err := readBounded(path, maxStateBytes)
	if err != nil {
		return RestoreIntent{}, err
	}
	var intent RestoreIntent
	if err := protocol.DecodeStrict(data, &intent, maxStateBytes); err != nil {
		return RestoreIntent{}, err
	}
	if intent.Schema != restoreIntentSchema || intent.Unit != unit || !digestRE.MatchString(intent.Target) ||
		!digestRE.MatchString(intent.Rejected) || intent.Target == intent.Rejected {
		return RestoreIntent{}, fmt.Errorf("%w: restore intent", ErrInvalid)
	}
	current, err := layout.Current()
	if err != nil {
		return RestoreIntent{}, err
	}
	if current != intent.Target && current != intent.Rejected {
		return RestoreIntent{}, fmt.Errorf("%w: current differs from recorded restore", ErrUnsafe)
	}
	bad, err := layout.KnownBad()
	if err != nil {
		return RestoreIntent{}, err
	}
	if bad[intent.Target] {
		return RestoreIntent{}, ErrKnownBad
	}
	if err := layout.VerifyRelease(intent.Target); err != nil {
		return RestoreIntent{}, fmt.Errorf("restore target cannot be restored: %w", err)
	}
	return intent, nil
}

func (layout Layout) finishRestore(unit string) error {
	path := layout.restoreIntentPath(unit)
	if err := layout.checkOwned(path, false); errors.Is(err, os.ErrNotExist) {
		return nil
	} else if err != nil {
		return err
	}
	intent, err := layout.readRestoreIntent(unit)
	if err != nil {
		return err
	}
	if err := layout.markKnownBad(intent.Rejected); err != nil {
		return err
	}
	if err := layout.markRestartPending(unit); err != nil {
		return err
	}
	if current, err := layout.Current(); err != nil {
		return err
	} else if current != intent.Target {
		if err := layout.flipCurrent(intent.Target); err != nil {
			return err
		}
	}
	if err := os.Remove(path); err != nil {
		return err
	}
	return syncDir(layout.Root)
}

// WatchdogUnit is the template unit that runs the watchdog for each role.
const WatchdogUnit = "terrascale-orchestrator-selfupdate-watchdog@.service"

// WatchdogLoggingDropin keeps systemd's own lines for each 15 s run out of the journal.
const WatchdogLoggingDropin = `[Service]
# Each 15 s run would log six systemd lines; keep notices and above.
LogLevelMax=notice
SyslogLevel=notice
`

// InstallWatchdogLoggingDropin writes WatchdogLoggingDropin below systemdDir
// on a host, one with the watchdog unit, and reports whether it changed it.
// systemd reads it from the next run.
func InstallWatchdogLoggingDropin(systemdDir string) (bool, error) {
	return installDropin(systemdDir, WatchdogUnit, "10-logging.conf", WatchdogLoggingDropin)
}

func installDropin(systemdDir, unit, file, dropin string) (bool, error) {
	if _, err := os.Stat(filepath.Join(systemdDir, unit)); errors.Is(err, os.ErrNotExist) {
		return false, nil
	} else if err != nil {
		return false, err
	}
	dir := filepath.Join(systemdDir, unit+".d")
	path := filepath.Join(dir, file)
	if current, err := os.ReadFile(path); err == nil && string(current) == dropin {
		return false, nil
	}
	if err := os.MkdirAll(dir, 0o755); err != nil {
		return false, err
	}
	return true, writeFileAtomic(path, []byte(dropin), 0o644)
}

func VerifyQualifiedBinaryUpdateCurrent(wire, delegationWire []byte, roots trust.Keyring, expected UpdateExpectation, now time.Time) (VerifiedBinary, error) {
	binary, err := VerifyBinaryUpdateCurrent(wire, delegationWire, roots, expected, now)
	if err != nil {
		return VerifiedBinary{}, err
	}
	envelope, err := trust.DecodeEnvelope(wire)
	if err != nil {
		return VerifiedBinary{}, err
	}
	var receipt BinaryUpdateReceipt
	if err := protocol.DecodeStrict(envelope.Payload, &receipt, trust.MaxPayloadBytes); err != nil {
		return VerifiedBinary{}, err
	}
	if receipt.Production == nil {
		return VerifiedBinary{}, fmt.Errorf("%w: signed update contains no independent qualification", ErrProductionQualification)
	}
	if _, err := VerifyProductionCurrent(receipt.Production.Qualification, receipt.Production.Delegation, roots,
		productionBinaryExpectation(binary.Receipt(), expected), now); err != nil {
		return VerifiedBinary{}, err
	}
	qualification, err := trust.DecodeEnvelope(receipt.Production.Qualification)
	if err != nil {
		return VerifiedBinary{}, err
	}
	if qualification.ExpiresAt.Before(binary.proof.expiresAt) {
		binary.proof.expiresAt = qualification.ExpiresAt
	}
	if len(receipt.Production.Delegation) > 0 {
		delegation, err := trust.DecodeEnvelope(receipt.Production.Delegation)
		if err != nil {
			return VerifiedBinary{}, err
		}
		if delegation.ExpiresAt.Before(binary.proof.expiresAt) {
			binary.proof.expiresAt = delegation.ExpiresAt
		}
	}
	return binary, nil
}

func signBinaryUpdateReceipt(binary BinaryReceipt, qualification Qualification, qualificationSHA256, cell, environment string,
	checker LineageChecker, delegationEnvelope trust.Envelope, roots trust.Keyring, privateKey ed25519.PrivateKey,
	now time.Time, validFor time.Duration, sequence uint64, migrationSHA256 string,
) (trust.Envelope, error) {
	if checker == nil {
		return trust.Envelope{}, fmt.Errorf("%w: no lineage checker", ErrLineage)
	}
	if validFor <= 0 || validFor > MaxUpdateReceiptLifetime {
		return trust.Envelope{}, fmt.Errorf("update receipt validity must be positive and no longer than %s", MaxUpdateReceiptLifetime)
	}
	if err := qualification.MatchBinary(binary, qualificationSHA256); err != nil {
		return trust.Envelope{}, err
	}
	verified, err := verifyUpdateDelegation(delegationEnvelope, roots, environment, currentAt(now))
	if err != nil {
		return trust.Envelope{}, err
	}
	if len(privateKey) != ed25519.PrivateKeySize {
		return trust.Envelope{}, trust.ErrKeyMismatch
	}
	signerKeyID, err := trust.KeyID(privateKey.Public().(ed25519.PublicKey))
	if err != nil || signerKeyID != verified.delegation.SubjectKeyID {
		return trust.Envelope{}, trust.ErrKeyMismatch
	}
	if err := checker.CheckLineage(verified.delegation.LineageBase, binary.SourceRevision, verified.delegation.Ref); err != nil {
		return trust.Envelope{}, fmt.Errorf("%w: %w", ErrLineage, err)
	}
	receipt := BinaryUpdateReceipt{
		Schema: UpdateReceiptSchema, Binary: binary, Cell: cell, DelegationSHA256: verified.digest,
		ReleaseSequence: sequence, SequenceMigrationSHA256: migrationSHA256,
		Lineage: SourceLineage{
			Repository: qualification.Repository, Workflow: qualification.Verification.Workflow, Ref: verified.delegation.Ref,
			LineageBase: verified.delegation.LineageBase, QualificationRunID: qualification.Verification.RunID,
			QualificationRunNum: qualification.Verification.RunNumber,
		},
	}
	if err := receipt.Validate(); err != nil {
		return trust.Envelope{}, err
	}
	if err := verified.authorize(receipt); err != nil {
		return trust.Envelope{}, err
	}
	expiresAt := now.Add(validFor)
	if delegationEnvelope.ExpiresAt.Before(expiresAt) {
		// The receipt is capped at its delegation's expiry. Refuse a cap
		// that would leave a receipt consumers reject almost at once.
		if remaining := delegationEnvelope.ExpiresAt.Sub(now); remaining < min(validFor, MinUpdateReceiptValidity) {
			return trust.Envelope{}, fmt.Errorf("update delegation expires in %s, less than the %s minimum receipt validity; renew the delegation",
				remaining.Round(time.Second), min(validFor, MinUpdateReceiptValidity))
		}
		expiresAt = delegationEnvelope.ExpiresAt
	}
	payload, err := trust.EncodePayload(receipt)
	if err != nil {
		return trust.Envelope{}, err
	}
	envelope, err := trust.Sign(payload, UpdateReceiptScope(receipt, environment), now, expiresAt, privateKey)
	if err != nil {
		return trust.Envelope{}, err
	}
	envelopeWire, err := trust.EncodeEnvelope(envelope)
	if err != nil {
		return trust.Envelope{}, err
	}
	delegationWire, err := trust.EncodeEnvelope(delegationEnvelope)
	if err != nil {
		return trust.Envelope{}, err
	}
	if _, err := VerifyBinaryUpdateCurrent(envelopeWire, delegationWire, roots,
		UpdateExpectation{Environment: environment, Cell: cell, Architecture: binary.GOARCH}, now); err != nil {
		return trust.Envelope{}, fmt.Errorf("signed update receipt fails consumer verification: %w", err)
	}
	return envelope, nil
}

func VerifyBinaryUpdateCurrent(envelopeWire, delegationWire []byte, roots trust.Keyring,
	expected UpdateExpectation, now time.Time,
) (VerifiedBinary, error) {
	receipt, proof, err := verifyBinaryUpdate(envelopeWire, delegationWire, roots, expected, currentAt(now))
	if err != nil {
		return VerifiedBinary{}, err
	}
	return VerifiedBinary{receipt: receipt, proof: proof}, nil
}

func verifyBinaryUpdate(envelopeWire, delegationWire []byte, roots trust.Keyring, expected UpdateExpectation,
	check envelopeCheck,
) (BinaryReceipt, receiptProof, error) {
	if err := validateEnvironment(expected.Environment); err != nil {
		return BinaryReceipt{}, receiptProof{}, err
	}
	if !ValidRegion(expected.Cell) || expected.Architecture != "amd64" && expected.Architecture != "arm64" {
		return BinaryReceipt{}, receiptProof{}, fmt.Errorf("%w: update expectation", ErrExpectationMismatch)
	}
	envelope, delegationEnvelope, err := decodeEnvelopePair(envelopeWire, delegationWire)
	if err != nil {
		return BinaryReceipt{}, receiptProof{}, err
	}
	verified, err := verifyUpdateDelegation(delegationEnvelope, roots, expected.Environment, check)
	if err != nil {
		return BinaryReceipt{}, receiptProof{}, err
	}
	receipt, err := decodeCanonicalPayload[BinaryUpdateReceipt](envelope.Payload)
	if err != nil {
		return BinaryReceipt{}, receiptProof{}, err
	}
	if err := receipt.Validate(); err != nil {
		return BinaryReceipt{}, receiptProof{}, err
	}
	if receipt.Cell != expected.Cell || receipt.Binary.GOARCH != expected.Architecture {
		return BinaryReceipt{}, receiptProof{}, ErrExpectationMismatch
	}
	if err := verified.authorize(receipt); err != nil {
		return BinaryReceipt{}, receiptProof{}, err
	}
	if envelope.IssuedAt.Before(delegationEnvelope.IssuedAt) || envelope.ExpiresAt.After(delegationEnvelope.ExpiresAt) {
		return BinaryReceipt{}, receiptProof{}, trust.ErrDelegationTime
	}
	if _, err := check(envelope, UpdateReceiptScope(receipt, expected.Environment),
		trust.Keyring{verified.delegation.SubjectKeyID: verified.publicKey},
		trust.Policy{MaxLifetime: MaxUpdateReceiptLifetime, ClockSkew: clockSkew}); err != nil {
		return BinaryReceipt{}, receiptProof{}, fmt.Errorf("verify binary update receipt: %w", err)
	}
	proof, err := proofFor(envelope)
	if err != nil {
		return BinaryReceipt{}, receiptProof{}, err
	}
	return receipt.Binary, proof, nil
}

func VerifyProductionCurrent(wire, delegationWire []byte, roots trust.Keyring, expected ProductionExpectation, now time.Time) (ProductionQualification, error) {
	var qualification ProductionQualification
	gates := []string{"runtime-ha", "workload-safety"}
	schema := ProductionQualificationSchema
	if expected.Role == FoundationWriterRole {
		schema = FoundationWriterQualificationSchema
		gates = append(gates, RootCredentialBoundaryGate)
	}
	validRuntime := expected.Runtime == ProductionRuntime
	if expected.Role == FoundationWriterRole {
		validRuntime = validRuntime && ValidOCIImageIDForRegion(expected.ImageOCID, expected.Cell)
	}
	if expected.Role == "netbird-manager" || expected.Runtime == NetBirdProductionRuntime {
		validRuntime = expected.Role == "netbird-manager" && expected.Runtime == NetBirdProductionRuntime &&
			expected.Cell == "GRU" && expected.Architecture == "arm64"
		gates = []string{"netbird-foundation", "netbird-recovery"}
	}
	if !ValidSourceRevision(expected.SourceRevision) || !digestPattern.MatchString(expected.ArtifactSHA256) ||
		!digestPattern.MatchString(expected.QualificationSHA256) || !ValidRegion(expected.Cell) ||
		!ValidEnvironment(expected.Environment) || !validRuntime ||
		expected.Architecture != "amd64" && expected.Architecture != "arm64" || !serviceRolePattern.MatchString(expected.Role) {
		return qualification, fmt.Errorf("%w: candidate scope", ErrProductionQualification)
	}
	envelope, err := trust.DecodeEnvelope(wire)
	if err != nil {
		return qualification, fmt.Errorf("%w: %w", ErrProductionQualification, err)
	}
	policy := trust.Policy{MaxLifetime: MaxUpdateReceiptLifetime}
	var payload []byte
	if len(delegationWire) == 0 {
		payload, err = trust.VerifyCurrent(envelope, ProductionQualificationScope(expected), roots, now, policy)
	} else {
		var delegationEnvelope trust.Envelope
		delegationEnvelope, err = trust.DecodeEnvelope(delegationWire)
		if err == nil {
			var delegation trust.VerifiedDelegation
			delegation, err = trust.VerifyDelegationCurrent(delegationEnvelope, roots, now, policy)
			if err == nil {
				payload, err = trust.VerifyDelegatedCurrent(envelope, ProductionQualificationScope(expected), delegation, now, policy)
			}
		}
	}
	if err != nil {
		return qualification, fmt.Errorf("%w: %w", ErrProductionQualification, err)
	}
	if err := protocol.DecodeStrict(payload, &qualification, trust.MaxPayloadBytes); err != nil {
		return qualification, fmt.Errorf("%w: %w", ErrProductionQualification, err)
	}
	if qualification.Schema != schema || qualification.Candidate != expected || len(qualification.Evidence) != len(gates) {
		return qualification, fmt.Errorf("%w: candidate or required gates", ErrProductionQualification)
	}
	for index, gate := range gates {
		evidence := qualification.Evidence[index]
		if evidence.Gate != gate || !digestPattern.MatchString(evidence.SHA256) ||
			evidence.Bytes <= 0 || evidence.Bytes > MaxProductionEvidenceBytes || evidence.CompletedAt.IsZero() ||
			evidence.CompletedAt.After(envelope.IssuedAt) {
			return qualification, fmt.Errorf("%w: %s evidence", ErrProductionQualification, gate)
		}
	}
	return qualification, nil
}

func owned(id, state, kind string, age time.Duration) oci.CloudVolumeBackup {
	return oci.CloudVolumeBackup{ID: id, VolumeID: volume, LifecycleState: state, Type: kind,
		CreatedAt: now.Add(-age), FreeformTags: scope.Tags(volume, entityid.Derive("test-backup", id)), ETag: "etag-" + id}
}

type fakeFencer struct {
	snapshot authority.Snapshot
	guardErr error
	guards   int
}

func (f *fakeFencer) Current() authority.Snapshot { return f.snapshot }
func (f *fakeFencer) Guard(context.Context, uint64) error {
	f.guards++
	return f.guardErr
}

func leader() authority.Snapshot {
	return authority.Snapshot{DeploymentID: "01ARZ3NDEKTSV4RRFFQ69G5FAV", Leader: true, Ready: true, Epoch: 3, Revision: 5, ExpiresAt: time.Now().Add(time.Minute)}
}

type fakeProvider struct {
	backups   map[string]oci.CloudVolumeBackup
	tokens    map[string]string
	creates   int
	deletes   []string
	onGet     func(*oci.CloudVolumeBackup)
	gone      map[string]bool
	goneErr   map[string]error
	goneReads map[string]int
}

func newFakeProvider(backups ...oci.CloudVolumeBackup) *fakeProvider {
	provider := &fakeProvider{backups: make(map[string]oci.CloudVolumeBackup), tokens: make(map[string]string), goneReads: make(map[string]int)}
	for _, backup := range backups {
		provider.backups[backup.ID] = backup
	}
	return provider
}

func (p *fakeProvider) CreateVolumeBackup(_ context.Context, volumeID, name, kind string, tags map[string]string, token string) (oci.CloudVolumeBackup, error) {
	if id, ok := p.tokens[token]; ok {
		return p.backups[id], nil
	}
	p.creates++
	backup := oci.CloudVolumeBackup{ID: fmt.Sprintf("created-%d", p.creates), VolumeID: volumeID, DisplayName: name,
		Type: kind, LifecycleState: "CREATING", CreatedAt: now, FreeformTags: maps.Clone(tags), ETag: "e"}
	p.backups[backup.ID] = backup
	p.tokens[token] = backup.ID
	return backup, nil
}

func (p *fakeProvider) ListVolumeBackups(_ context.Context, volumeID string) ([]oci.CloudVolumeBackup, error) {
	var found []oci.CloudVolumeBackup
	for _, backup := range p.backups {
		if backup.VolumeID == volumeID {
			found = append(found, backup)
		}
	}
	return found, nil
}

func (p *fakeProvider) ListCompartmentVolumeBackups(context.Context) ([]oci.CloudVolumeBackup, error) {
	var found []oci.CloudVolumeBackup
	for _, backup := range p.backups {
		found = append(found, backup)
	}
	return found, nil
}

func (p *fakeProvider) VolumeGone(_ context.Context, volumeID string) (bool, error) {
	p.goneReads[volumeID]++
	return p.gone[volumeID], p.goneErr[volumeID]
}

func (p *fakeProvider) GetVolumeBackup(_ context.Context, id string) (oci.CloudVolumeBackup, error) {
	backup, ok := p.backups[id]
	if !ok {
		return oci.CloudVolumeBackup{}, errors.New("not found")
	}
	if p.onGet != nil {
		p.onGet(&backup)
	}
	return backup, nil
}

func (p *fakeProvider) DeleteVolumeBackup(_ context.Context, id, etag string) error {
	if p.backups[id].ETag != etag {
		return oci.ErrStaleETag
	}
	delete(p.backups, id)
	p.deletes = append(p.deletes, id)
	return nil
}

func runner(provider *fakeProvider, fencer *fakeFencer) Runner {
	return Runner{Scope: scope, Provider: provider, Fencer: fencer,
		Volumes: func(context.Context) ([]string, error) { return []string{volume}, nil },
		Now:     func() time.Time { return now }}
}

func orphan(id, volumeID string, age time.Duration) oci.CloudVolumeBackup {
	return oci.CloudVolumeBackup{ID: id, VolumeID: volumeID, LifecycleState: "AVAILABLE", Type: TypeFull,
		CreatedAt: now.Add(-age), FreeformTags: scope.Tags(volumeID, entityid.Derive("test-backup", id)), ETag: "etag-" + id}
}

func (scope Scope) Tags(volumeID, key string) map[string]string {
	return map[string]string{
		tagManagedBy: managedByValue, tagOwner: scope.Owner, tagRegion: string(scope.Region),
		tagResource: resourceValue, tagBackupVolume: volumeID, tagBackupKey: key, tagComponent: componentValue,
	}
}

func (scope Scope) Owns(backup oci.CloudVolumeBackup, volumeID string) bool {
	tags := backup.FreeformTags
	return backup.ID != "" && backup.VolumeID == volumeID && tags[tagManagedBy] == managedByValue &&
		tags[tagOwner] == scope.Owner && tags[tagRegion] == string(scope.Region) &&
		tags[tagResource] == resourceValue && tags[tagBackupVolume] == volumeID && entityid.Valid(tags[tagBackupKey])
}

func inProgress(state string) bool {
	return state == "CREATING" || state == "REQUEST_RECEIVED"
}

func attemptKey(slot string, owned []oci.CloudVolumeBackup) string {
	failed := make(map[string]bool)
	for _, backup := range owned {
		if backup.LifecycleState == "FAULTY" {
			failed[backup.FreeformTags[tagBackupKey]] = true
		}
	}
	for attempt := 0; ; attempt++ {
		key := entityid.Derive("backup-attempt", slot, fmt.Sprint(attempt))
		if !failed[key] {
			return key
		}
	}
}

func Plan(scope Scope, volumeID string, backups []oci.CloudVolumeBackup, now time.Time) []Action {
	var owned []oci.CloudVolumeBackup
	for _, backup := range backups {
		if scope.Owns(backup, volumeID) {
			owned = append(owned, backup)
		}
	}
	// Newest first.
	slices.SortFunc(owned, func(a, b oci.CloudVolumeBackup) int { return b.CreatedAt.Compare(a.CreatedAt) })
	var actions []Action
	creating := slices.ContainsFunc(owned, func(backup oci.CloudVolumeBackup) bool { return inProgress(backup.LifecycleState) })
	var latest time.Time
	sinceFull, sawFull := 0, false
	for _, backup := range owned {
		if backup.LifecycleState != "AVAILABLE" && !inProgress(backup.LifecycleState) {
			continue
		}
		if latest.IsZero() {
			latest = backup.CreatedAt
		}
		if !sawFull {
			if backup.Type == TypeFull {
				sawFull = true
			} else {
				sinceFull++
			}
		}
	}
	if !creating && (latest.IsZero() || now.Sub(latest) >= backupInterval) {
		kind := TypeIncremental
		if !sawFull || sinceFull+1 >= fullEvery {
			kind = TypeFull
		}
		slot := fmt.Sprintf("%s/%d", volumeID, now.UTC().Truncate(backupInterval).Unix())
		actions = append(actions, Action{Kind: ActionCreate, VolumeID: volumeID, Type: kind,
			Key: attemptKey(slot, owned)})
	}
	kept := 0
	for _, backup := range owned {
		if backup.LifecycleState != "AVAILABLE" {
			continue
		}
		kept++
		if kept > retain {
			actions = append(actions, Action{Kind: ActionDelete, VolumeID: volumeID, BackupID: backup.ID})
		}
	}
	return actions
}

// Package backup schedules crash-consistent OCI block volume backups of
// retained TerraBase volumes and prunes owned backups beyond retention.
// Every OCI mutation is preceded by an authority epoch guard.
package backup

import "time"

// Backup types accepted by OCI CreateVolumeBackup.
const (
	TypeFull        = "FULL"
	TypeIncremental = "INCREMENTAL"
)

const (
	backupInterval  = 24 * time.Hour
	runInterval     = 15 * time.Minute
	orphanRetention = 30 * 24 * time.Hour
	// Keeping a complete full-backup cadence preserves its latest FULL.
	retain    = 7
	fullEvery = 7
)

// Retention must preserve a complete FULL backup cadence.
var _ [retain - fullEvery]struct{}

func (runner Runner) validate() error {
	if runner.Provider == nil || runner.Fencer == nil || runner.Volumes == nil || runner.Scope.Owner == "" || runner.Scope.Region == "" {
		return errors.New("volume backup runner requires a provider, authority fencer, volume source and owner scope")
	}
	return nil
}

func (runner Runner) RunOnce(ctx context.Context) (Report, error) {
	if err := runner.validate(); err != nil {
		return Report{}, err
	}
	snapshot := runner.Fencer.Current()
	if !snapshot.CanMutate() {
		return Report{}, authority.ErrNotLeader
	}
	epoch := snapshot.Epoch
	now := time.Now
	if runner.Now != nil {
		now = runner.Now
	}
	volumes, err := runner.Volumes(ctx)
	partial := errors.Is(err, ErrPartialVolumes)
	if err != nil && !partial {
		return Report{}, fmt.Errorf("list volumes to back up: %w", err)
	}
	var report Report
	var failures []error
	if partial {
		failures = append(failures, fmt.Errorf("list volumes to back up: %w", err))
	}
	protected := make([]string, 0, len(volumes))
	for _, volumeID := range volumes {
		gone, err := runner.Provider.VolumeGone(ctx, volumeID)
		if err != nil {
			protected = append(protected, volumeID)
			failures = append(failures, err)
			continue
		}
		if gone {
			continue
		}
		protected = append(protected, volumeID)
		backups, err := runner.Provider.ListVolumeBackups(ctx, volumeID)
		if err != nil {
			failures = append(failures, err)
			continue
		}
		for _, action := range Plan(runner.Scope, volumeID, backups, now()) {
			if err := runner.guard(ctx, epoch); err != nil {
				return report, errors.Join(append(failures, err)...)
			}
			switch action.Kind {
			case ActionCreate:
				created, err := runner.Provider.CreateVolumeBackup(ctx, volumeID,
					"ts-member-data-backup-"+retryToken(runner.Scope, action.Key)[:12], action.Type,
					runner.Scope.Tags(volumeID, action.Key), retryToken(runner.Scope, action.Key))
				if err != nil {
					failures = append(failures, err)
					continue
				}
				report.Created = append(report.Created, created.ID)
				recordBackup(ctx, runner.Scope, epoch, volumeID, action, created.ID)
			case ActionDelete:
				deleted, err := runner.prune(ctx, epoch, volumeID, action.BackupID)
				if err != nil {
					failures = append(failures, err)
					continue
				}
				if deleted {
					report.Deleted = append(report.Deleted, action.BackupID)
				} else {
					report.Skipped = append(report.Skipped, action.BackupID)
				}
			}
		}
	}
	if !partial {
		if err := runner.pruneOrphans(ctx, epoch, protected, now(), &report); err != nil {
			failures = append(failures, err)
		}
	}
	return report, errors.Join(failures...)
}

func (runner Runner) pruneOrphans(ctx context.Context, epoch uint64, placed []string, now time.Time, report *Report) error {
	backups, err := runner.Provider.ListCompartmentVolumeBackups(ctx)
	if err != nil {
		return fmt.Errorf("list compartment volume backups: %w", err)
	}
	live := make(map[string]bool, len(placed))
	for _, volumeID := range placed {
		live[volumeID] = true
	}
	retention := orphanRetention
	gone := make(map[string]bool)
	var failures []error
	for _, backup := range backups {
		volumeID := backup.VolumeID
		if volumeID == "" || live[volumeID] || !runner.Scope.Owns(backup, volumeID) ||
			backup.LifecycleState != "AVAILABLE" {
			continue
		}
		removed, checked := gone[volumeID]
		if !checked {
			gone[volumeID] = false
			removed, err = runner.Provider.VolumeGone(ctx, volumeID)
			if err != nil {
				failures = append(failures, err)
				continue
			}
			gone[volumeID] = removed
		}
		// Capture termination before OCI purges the source, even for young backups.
		if !removed || now.Sub(backup.CreatedAt) < retention {
			continue
		}
		deleted, err := runner.prune(ctx, epoch, volumeID, backup.ID)
		if errors.Is(err, authority.ErrFenced) {
			return errors.Join(append(failures, err)...)
		}
		switch {
		case err != nil:
			failures = append(failures, err)
		case deleted:
			report.Deleted = append(report.Deleted, backup.ID)
		default:
			report.Skipped = append(report.Skipped, backup.ID)
		}
	}
	return errors.Join(failures...)
}

func (runner Runner) prune(ctx context.Context, epoch uint64, volumeID, backupID string) (bool, error) {
	current, err := runner.Provider.GetVolumeBackup(ctx, backupID)
	if err != nil {
		return false, err
	}
	if !runner.Scope.Owns(current, volumeID) || current.LifecycleState != "AVAILABLE" || current.ETag == "" {
		return false, nil
	}
	if err := runner.guard(ctx, epoch); err != nil {
		return false, err
	}
	return true, runner.Provider.DeleteVolumeBackup(ctx, backupID, current.ETag)
}

func (runner Runner) guard(ctx context.Context, epoch uint64) error {
	if snapshot := runner.Fencer.Current(); !snapshot.CanMutate() || snapshot.Epoch != epoch {
		return authority.ErrFenced
	}
	if err := runner.Fencer.Guard(ctx, epoch); err != nil {
		return fmt.Errorf("volume backup authority was fenced: %w", err)
	}
	return nil
}

func retryToken(scope Scope, key string) string {
	sum := sha256.Sum256([]byte(scope.Owner + "\x00" + string(scope.Region) + "\x00" + key))
	return hex.EncodeToString(sum[:])
}

func recordBackup(ctx context.Context, scope Scope, epoch uint64, volumeID string, action Action, backupID string) {
	key := "backup:" + backupID
	if decisionlog.Correlated(key) != "" {
		return
	}
	id := decisionlog.Record(ctx, decisionlog.Decision{
		Region:  string(scope.Region),
		Actor:   decisionlog.Actor{Slice: "storage"},
		Kind:    decisionlog.KindBackupTaken,
		Subject: decisionlog.Subject{Kind: "volume", ID: volumeID},
		Summary: "Started a " + strings.ToLower(action.Type) + " backup of volume " + volumeID,
		Reason:  "The volume backup policy interval elapsed without a backup.",
		Rule:    "storage.volume_backup",
		Status:  decisionlog.StatusInProgress,
		Epoch:   epoch,
		Attrs:   map[string]string{"backup_id": backupID, "type": action.Type},
	})
	decisionlog.Correlate(key, id)
}

func (s Snapshot) CanMutate() bool {
	return entityid.Valid(s.DeploymentID) && s.Ready && s.Leader && s.Epoch > 0 && s.Revision > 0 &&
		!s.ExpiresAt.IsZero() && time.Now().Before(s.ExpiresAt)
}

func Default() Recorder {
	if holder := defaultRecorder.Load(); holder != nil {
		return holder.recorder
	}
	return nil
}

func Record(ctx context.Context, decision Decision) string {
	if recorder := Default(); recorder != nil {
		return recorder.Record(ctx, decision)
	}
	return LogRecorder{}.Record(ctx, decision)
}

func (recorder LogRecorder) Record(ctx context.Context, decision Decision) string {
	decision = decision.Normalize(time.Now())
	logger := recorder.Logger
	if logger == nil {
		logger = slog.Default()
	}
	attrs := []slog.Attr{slog.String(observability.ComponentKey, "decision"), slog.Bool(observability.EventKey, true),
		slog.String("decision_id", decision.ID),
		slog.String("kind", string(decision.Kind)), slog.String("actor", decision.Actor.Slice),
		slog.String("subject", decision.Subject.String()), slog.String("status", string(decision.Status))}
	if decision.Region != "" {
		attrs = append(attrs, slog.String("region", decision.Region))
	}
	if decision.Reason != "" {
		attrs = append(attrs, slog.String("reason", decision.Reason))
	}
	if decision.ParentID != "" {
		attrs = append(attrs, slog.String("parent_id", decision.ParentID))
	}
	logger.LogAttrs(ctx, slog.LevelInfo, decision.Summary, attrs...)
	return decision.ID
}

func Correlate(key, id string) {
	if key == "" || id == "" {
		return
	}
	correlations.Lock()
	defer correlations.Unlock()
	if _, exists := correlations.ids[key]; !exists {
		correlations.order = append(correlations.order, key)
	}
	correlations.ids[key] = id
	for len(correlations.order) > maxCorrelations {
		delete(correlations.ids, correlations.order[0])
		correlations.order = correlations.order[1:]
	}
}

func Correlated(key string) string {
	correlations.Lock()
	defer correlations.Unlock()
	return correlations.ids[key]
}
